/**
 * Word lists behind the readability and reference rules.
 *
 * These are editorial conventions, not universal truths, so every entry says
 * whether it is safe to replace outright (`fix`) or should merely be raised for
 * the author to decide (`confirm`).
 */
import type { Severity } from "./types.ts";

export interface Entry {
  /** The surface form to look for. */
  readonly from: string;
  /** The preferred form. */
  readonly to: string;
  readonly severity: Severity;
  /** Extra explanation appended to the finding's message. */
  readonly note?: string;
  /**
   * Entries that are style preferences rather than mistakes ship switched off.
   * They stay in the list so 「ルール設定」 can offer them one checkbox away.
   */
  readonly defaultEnabled?: boolean;
}

