/**
 * 表現をもっと簡潔に: same meaning, fewer characters. The checklist's own
 * examples 「〜を有する」→「〜をもつ」 and 「明らかになった」→「わかった」 head the list.
 */
export const VERBOSE: readonly Entry[] = Object.freeze([
  { from: "を有する", to: "をもつ", severity: "fix" },
  { from: "を有し", to: "をもち", severity: "fix" },
  // 「明らかになった」は結論を述べる定型で、「わかった」に直すと口語に寄る。
  // 単調な繰り返しのときだけ効く助言なので、既定では黙らせる。
  {
    from: "明らかになった",
    to: "わかった",
    severity: "confirm",
    note: "単調にならない範囲で",
    defaultEnabled: false,
  },
  {
    from: "明らかとなった",
    to: "わかった",
    severity: "confirm",
    note: "単調にならない範囲で",
    defaultEnabled: false,
  },
  { from: "することができる", to: "できる", severity: "fix" },
  { from: "することができた", to: "できた", severity: "fix" },
  { from: "することが可能である", to: "できる", severity: "fix" },
  { from: "することが可能", to: "できる", severity: "confirm" },
  { from: "を行った", to: "した", severity: "confirm", note: "動詞化できるなら短く" },
  { from: "を行う", to: "する", severity: "confirm", note: "動詞化できるなら短く" },
  { from: "を実施した", to: "した", severity: "confirm" },
  { from: "という事", to: "ということ", severity: "fix" },
  { from: "に関して", to: "について", severity: "confirm" },
  { from: "に対しての", to: "に対する", severity: "fix" },
  // 「溶液の中で」のように場所を示す用法は冗長ではないので、既定では黙らせる。
  { from: "の中で", to: "で", severity: "confirm", defaultEnabled: false },
  { from: "を用いて行った", to: "を用いた", severity: "confirm" },
  // 「〜であると考えられる」は主語が体言のときに要る形で、削ると文が壊れる場合がある。
  { from: "であると考えられる", to: "と考えられる", severity: "confirm", defaultEnabled: false },
  { from: "ということができる", to: "といえる", severity: "fix" },
  { from: "を目的として", to: "のため", severity: "confirm" },
  // 列挙の定型表現として定着しているので、既定では黙らせる。
  { from: "が挙げられる", to: "がある", severity: "confirm", defaultEnabled: false },
  { from: "することにより", to: "して", severity: "confirm" },
  // 「Aにおいては B だが、Cでは」のような対比では「においては」が要る。
  { from: "においては", to: "では", severity: "confirm", defaultEnabled: false },
]);

