/**
 * 「この原稿に出てくる化合物番号／文献番号を並べて見せる」ための走査.
 *
 * This is not a rule — nothing here is a mistake. It answers the question a
 * reviewer asks before reading: *what is in this manuscript, and where?* A
 * compound mentioned once is usually a compound whose characterisation got
 * dropped; a reference number with a gap before it is usually a citation that
 * lost its entry. Both are visible at a glance in a list and invisible in prose.
 *
 * Offsets are kept so the task pane can jump to each mention, which is why every
 * item carries its occurrences rather than just a count.
 */
import { matchAll, escapeRegExp } from "./text.ts";
import { UNITS } from "./dict.ts";
import { LABEL_END } from "./labels.ts";

/** One place a label appears, in the coordinates `locateFindings` understands. */
export interface Occurrence {
  readonly paragraphIndex: number;
  readonly start: number;
  /** The exact text at that offset, used to resolve the Word range. */
  readonly text: string;
}

export interface InventoryItem {
  /** How the label is shown in the list: 「1a」「12」. */
  readonly label: string;
  readonly occurrences: readonly Occurrence[];
}

/** Numeric-then-alphabetic ordering, so 2 sorts before 10 and 1a before 1b. */
function bySeries(a: InventoryItem, b: InventoryItem): number {
  const parse = (label: string): [number, string] => {
    const m = /^(\d+)([a-z]*)$/u.exec(label);
    return m ? [Number(m[1]), m[2]!] : [Number.MAX_SAFE_INTEGER, label];
  };
  const [an, al] = parse(a.label);
  const [bn, bl] = parse(b.label);
  return an - bn || al.localeCompare(bl);
}

/** Collects occurrences into items, preserving first-seen order within a label. */
function collect(entries: ReadonlyArray<{ label: string; at: Occurrence }>): InventoryItem[] {
  const byLabel = new Map<string, Occurrence[]>();
  for (const { label, at } of entries) {
    if (!byLabel.has(label)) byLabel.set(label, []);
    byLabel.get(label)!.push(at);
  }
  return [...byLabel.entries()]
    .map(([label, occurrences]) => ({ label, occurrences }))
    .sort(bySeries);
}

// --- 化合物番号 ------------------------------------------------------------

const COMPOUND_WORD = /(?:compounds?|化合物)\s*(\d{1,4})([a-z])?/giu;
const COMPOUND_LABEL = new RegExp(`(?<![A-Za-z0-9.])(\\d{1,4})([a-z])${LABEL_END}`, "gu");
const COMPOUND_RANGE = new RegExp(
  `(?<![A-Za-z0-9.])(\\d{1,4})([a-z])\\s*[–—−-]\\s*(\\d{1,4})?([a-z])${LABEL_END}`,
  "gu",
);

function letterSpan(from: string, to: string): string[] {
  const start = from.charCodeAt(0);
  const end = to.charCodeAt(0);
  if (end <= start) return [];
  const letters: string[] = [];
  for (let code = start; code <= end; code += 1) letters.push(String.fromCharCode(code));
  return letters;
}

/**
 * Why a mention is believed to be a compound number.
 *
 * `bold` is a *proposal*: the text alone cannot see boldness, so the Office
 * layer confirms or drops those. The other two are settled here.
 */
export type Evidence = "word" | "label" | "bold";

export interface CompoundMention {
  readonly label: string;
  readonly at: Occurrence;
  readonly evidence: Evidence;
}

// --- 太字を化合物番号とみなすための線引き ---------------------------------
//
// Manuscripts set compound numbers in bold, which makes boldness the strongest
// signal available — far better than any pattern, because it is what the author
// meant. But three other things are bold in the same documents, and each has to
// be subtracted or the list fills with rubbish.

/** 図表番号も太字にする。数字の直前にこれがあれば化合物ではない。 */
const FIGURE_LABEL =
  /(?:Fig(?:ures?|s?)?\.?|Tables?|Schemes?|Charts?|Eq(?:uations?|ns?)?\.?|Entry|Entries|Refs?\.?|図|表|式|スキーム|チャート)\s*$/iu;

/** 「Figures 1 and 2」「図 1、2」 — the label reaches past the connector to the next number. */
const CONNECTOR = /^[\s,、and&+\-–—]*$/iu;

/** How far back to look for a figure label. Long enough for "Figures 1 and ". */
const LABEL_LOOKBACK = 28;

/** 発行年は文献リストでも本文でも太字になりうる。 */
const YEAR = /^(?:19|20)\d{2}$/u;

/**
 * Units close enough to the number that a bold 「25」 is a quantity, not a label.
 *
 * Built from the same `UNITS` the spacing rule uses, longest first so that 「mL」
 * is not read as 「m」 followed by a stray L. The boundary is spelled out rather
 * than `\\b`: 「80 ℃」 ends in a character that is not a word character at all, so
 * `\\b` finds no boundary there and the temperature was slipping through as a
 * candidate compound number.
 */
const UNIT_AHEAD = new RegExp(
  `^\\s*(?:${[...UNITS, "%"].sort((a, b) => b.length - a.length).map(escapeRegExp).join("|")})(?![A-Za-z0-9])`,
  "u",
);

/** 「数字（＋英小文字）」。ラベルと同じく、直後の電荷表記は末尾として認める。 */
const BOLD_TOKEN = new RegExp(`(?<![A-Za-z0-9.])(\\d{1,4})([a-z])?${LABEL_END}`, "gu");

/** Every 「数字（＋英小文字）」 token, with the ones that cannot be compounds removed. */
export function boldCandidates(text: string): Array<{ start: number; token: string }> {
  const brackets = [...matchAll(/\[[^\]]*\]/gu, text)].map((m) => ({
    start: m.index,
    end: m.index + m[0].length,
  }));

  const candidates: Array<{ start: number; token: string }> = [];
  for (const m of matchAll(BOLD_TOKEN, text)) {
    const token = m[0];
    if (YEAR.test(m[1]!) && m[2] === undefined) continue;
    if (brackets.some((b) => m.index >= b.start && m.index < b.end)) continue;
    if (UNIT_AHEAD.test(text.slice(m.index + token.length))) continue;

    // 「Figure 1」 and, through the connector test, 「Figures 1 and 2」.
    const before = text.slice(Math.max(0, m.index - LABEL_LOOKBACK), m.index);
    if (FIGURE_LABEL.test(before)) continue;
    const viaConnector = /(\d+)([\s,、and&+\-–—]*)$/iu.exec(before);
    if (viaConnector && CONNECTOR.test(viaConnector[2]!)) {
      const upstream = before.slice(0, before.length - viaConnector[0].length);
      if (FIGURE_LABEL.test(upstream)) continue;
    }

    candidates.push({ start: m.index, token });
  }
  return candidates;
}

/**
 * 本文に出てくる化合物番号の候補.
 *
 * Three kinds of evidence, in descending order of certainty:
 *
 * - `word` — 「化合物 5」 / "compound 5" says so outright.
 * - `label` — a series label (5a) or a range (1a–f, expanded to six compounds),
 *   backed by `compoundLabels()` so that 「18d」 is not read as 18 days.
 * - `bold` — a number the author set in bold. Proposed here, confirmed by Word.
 *
 * `skipParagraphs` takes the bibliography out: a reference entry is full of bold
 * years and volume numbers, and none of them is a compound.
 */
export function compoundMentions(
  paragraphs: readonly string[],
  labels: ReadonlySet<string>,
  skipParagraphs: ReadonlySet<number> = new Set(),
): CompoundMention[] {
  const mentions: CompoundMention[] = [];

  paragraphs.forEach((text, paragraphIndex) => {
    if (skipParagraphs.has(paragraphIndex)) return;
    const ranges: Array<{ start: number; end: number }> = [];
    const claimed = new Set<number>();

    for (const m of matchAll(COMPOUND_RANGE, text)) {
      const [whole, stem, first, secondStem, last] = m as unknown as
        [string, string, string, string | undefined, string];
      if (secondStem !== undefined && secondStem !== stem) continue;
      const letters = letterSpan(first, last);
      if (letters.length === 0) continue;
      ranges.push({ start: m.index, end: m.index + whole.length });
      const at: Occurrence = { paragraphIndex, start: m.index, text: whole };
      for (const letter of letters) mentions.push({ label: `${stem}${letter}`, at, evidence: "label" });
    }

    const insideRange = (at: number): boolean => ranges.some((r) => at >= r.start && at < r.end);

    for (const m of matchAll(COMPOUND_LABEL, text)) {
      if (!labels.has(m[0])) continue;
      if (insideRange(m.index)) continue; // already counted as part of the range
      claimed.add(m.index);
      mentions.push({
        label: m[0],
        at: { paragraphIndex, start: m.index, text: m[0] },
        evidence: "label",
      });
    }

    for (const m of matchAll(COMPOUND_WORD, text)) {
      // 「化合物 18a」 — the label half is already counted above; only 「化合物 5」,
      // with no letter, adds something.
      if (m[2] !== undefined) continue;
      const digitsAt = m.index + m[0].lastIndexOf(m[1]!);
      claimed.add(digitsAt);
      mentions.push({
        label: m[1]!,
        at: { paragraphIndex, start: m.index, text: m[0] },
        evidence: "word",
      });
    }

    for (const candidate of boldCandidates(text)) {
      if (claimed.has(candidate.start) || insideRange(candidate.start)) continue;
      mentions.push({
        label: candidate.token,
        at: { paragraphIndex, start: candidate.start, text: candidate.token },
        evidence: "bold",
      });
    }
  });

  return mentions;
}

/** Groups confirmed mentions into the list the pane shows. */
export function buildInventory(mentions: readonly CompoundMention[]): InventoryItem[] {
  return collect(mentions.map(({ label, at }) => ({ label, at })));
}

/** Text-only inventory: everything but the bold proposals. Used by the tests. */
export function compoundInventory(
  paragraphs: readonly string[],
  labels: ReadonlySet<string>,
): InventoryItem[] {
  return buildInventory(
    compoundMentions(paragraphs, labels).filter((m) => m.evidence !== "bold"),
  );
}

// --- 文献番号 --------------------------------------------------------------

const BRACKET_CITATION = /\[\s*\d+(?:\s*[,、–—−-]\s*\d+)*\s*\]/gu;
const PAREN_CITATION = /(?<![A-Za-z0-9])\(\s*\d+(?:\s*[,、–—−-]\s*\d+)*\s*\)(?![A-Za-z0-9])/gu;
const NUMBER_RUN = /\d+/gu;
const RANGE_SEPARATOR = /[–—−-]/u;

/** The reference numbers a citation marker stands for, ranges expanded. */
export function citedNumbers(marker: string): number[] {
  const inner = marker.slice(1, -1);
  const numbers = [...matchAll(NUMBER_RUN, inner)];
  const cited: number[] = [];

  numbers.forEach((m, i) => {
    const value = Number(m[0]);
    if (i === 0) {
      cited.push(value);
      return;
    }
    const previous = numbers[i - 1]!;
    const between = inner.slice(previous.index + previous[0].length, m.index);
    if (RANGE_SEPARATOR.test(between)) {
      // 「[4–6]」 means 4, 5 and 6.
      for (let n = Number(previous[0]) + 1; n <= value; n += 1) cited.push(n);
    } else {
      cited.push(value);
    }
  });

  return [...new Set(cited)].sort((a, b) => a - b);
}

/**
 * 本文に出てくる文献番号の一覧.
 *
 * `(1)` is only read as a citation when the document uses no `[1]` at all —
 * otherwise a parenthesised number is an equation, a compound, or a yield, and
 * every one of those would land in the list as a phantom reference.
 */
export function citationInventory(paragraphs: readonly string[]): InventoryItem[] {
  const brackets = paragraphs.some((text) => [...matchAll(BRACKET_CITATION, text)].length > 0);
  const pattern = brackets ? BRACKET_CITATION : PAREN_CITATION;

  const entries: Array<{ label: string; at: Occurrence }> = [];
  paragraphs.forEach((text, paragraphIndex) => {
    for (const m of matchAll(pattern, text)) {
      const at: Occurrence = { paragraphIndex, start: m.index, text: m[0] };
      for (const number of citedNumbers(m[0])) entries.push({ label: String(number), at });
    }
  });

  return collect(entries);
}

/** Reference numbers that nothing cites, between 1 and the highest cited. */
export function missingCitations(items: readonly InventoryItem[]): number[] {
  const cited = new Set(items.map((item) => Number(item.label)).filter(Number.isFinite));
  if (cited.size === 0) return [];
  const highest = Math.max(...cited);
  const gaps: number[] = [];
  for (let n = 1; n <= highest; n += 1) if (!cited.has(n)) gaps.push(n);
  return gaps;
}
