/**
 * The word lists a rule is driven by, so 「ルール設定」 can show them and let the
 * user switch off individual entries. Only dictionary-backed rules appear here.
 */
export const RULE_ENTRIES: Readonly<Record<string, readonly Entry[]>> = Object.freeze({
  "kanji-to-kana": KANJI_TO_KANA,
  "kanji-meaning": KANJI_MEANING,
  "verbose-expression": VERBOSE,
  "casual-expression": CASUAL,
  "journal-abbrev": JOURNAL_ABBREV,
});

/** 表記ゆれの組。置換先が文書の多数派で決まるので、一覧は読むだけです。 */
export const RULE_GROUPS: Readonly<Record<string, readonly (readonly string[])[]>> = Object.freeze({
  "notation-variance": VARIANT_GROUPS,
});

/** Identifies one entry of one dictionary rule, for the disabled-entry set. */
export function entryKey(ruleId: string, from: string): string {
  return `${ruleId}:${from}`;
}

/**
 * Entries that ship switched off — style preferences whose wrong calls would
 * outnumber their right ones. They are ordinary entries otherwise: one checkbox
 * in 「ルール設定」 brings any of them back.
 */
export const DEFAULT_DISABLED_ENTRIES: readonly string[] = Object.freeze(
  Object.entries(RULE_ENTRIES).flatMap(([ruleId, entries]) =>
    entries.filter((entry) => entry.defaultEnabled === false).map((entry) => entryKey(ruleId, entry.from)),
  ),
);

/** True when the rule ships switched on. */
export function enabledByDefault(ruleId: string): boolean {
  return RULE_DOCS[ruleId]?.defaultEnabled ?? true;
}
