/**
 * 本文の引用番号と、末尾の文献リストを結びつける.
 *
 * `[3]` on its own tells a reviewer nothing. What they want to know is *which
 * paper* that is, and whether the entry exists at all — a citation with no entry
 * and an entry nobody cites are both common, and both invisible until someone
 * lines the two lists up by hand.
 *
 * The bibliography is found the way a reader finds it: a heading near the end
 * that says 「参考文献」 or "References", followed by numbered paragraphs. Failing
 * that, a run of numbered paragraphs at the end of the document is taken as the
 * list, since that is what one looks like even when the heading is missing.
 */
import { matchAll } from "./text.ts";

export interface BibliographyEntry {
  readonly number: number;
  readonly paragraphIndex: number;
  /** The entry without its leading number, as written. */
  readonly text: string;
  /** Offset of the 「[2]」 marker within the paragraph, for jumping to it. */
  readonly start: number;
  /** That marker exactly as written, e.g. 「[2]」. */
  readonly marker: string;
}

/** 「参考文献」「References」「5. References」— the heading, on its own line. */
const HEADING = /^\s*(?:\d+[.．]?\s*)?(?:references?|bibliography|literature\s+cited|参考文献|引用文献|文\s*献)\s*[:：]?\s*$/iu;

/** 「1. …」「(1) …」— a numbered entry that owns its paragraph. */
const LEADING_NUMBER = /^\s*(?:\(\s*(\d{1,3})\s*\)|(\d{1,3})\s*[.．)]）?)\s*/u;

/** 「[1]」 — the one marker form that also appears mid-paragraph. */
const BRACKET_MARKER = /\[\s*(\d{1,3})\s*\]/gu;

/**
 * An entry names authors and a journal, so it is never shorter than this.
 * 「1. はじめに」 is a section heading and has to stay out of the list.
 */
const MIN_ENTRY_LENGTH = 8;

interface RawEntry {
  readonly number: number;
  readonly text: string;
  readonly start: number;
  readonly marker: string;
}

/**
 * The entries inside one paragraph — usually one, sometimes all of them.
 *
 * A bibliography is often typed as a single running paragraph:
 * 「[1] I. Osaka et al. J. Mater. Chem. C, 2020, 8, 14262. [2] J. Kido et al. …」.
 * Reading one entry per paragraph gets the first reference and swallows every
 * other one as part of its title, so `[n]` markers are split on wherever they
 * appear.
 *
 * The numbers have to keep climbing for a marker to start a new entry. A `[3]`
 * that appears inside an entry's own text — a citation within a title, say — is
 * a step backwards or a repeat, and is left as part of the entry it sits in.
 *
 * The 「1.」 and 「(1)」 forms are only honoured at the very start of a paragraph.
 * Mid-paragraph they are indistinguishable from a page number or a sentence
 * ending in a numeral, and splitting on those would shred every entry.
 */
export function splitEntries(text: string): RawEntry[] {
  // A marker starts an entry unless it is glued to the back of a word. Entries
  // are usually separated by 「. 」 but 「。[2]」 and 「1585.[2]」 happen too, so the
  // test is what must *not* precede it rather than what must.
  const markers = [...matchAll(BRACKET_MARKER, text)].filter(
    (m) => m.index === 0 || !/[A-Za-z0-9]/u.test(text[m.index - 1] ?? ""),
  );

  const accepted: Array<{ index: number; marker: string; number: number }> = [];
  let highest = 0;
  for (const m of markers) {
    const number = Number(m[1]);
    if (number <= highest) continue;
    accepted.push({ index: m.index, marker: m[0], number });
    highest = number;
  }

  if (accepted.length > 0) {
    const entries: RawEntry[] = [];
    accepted.forEach((marker, i) => {
      const from = marker.index + marker.marker.length;
      const to = accepted[i + 1]?.index ?? text.length;
      const body = text.slice(from, to).trim();
      if (body.length < MIN_ENTRY_LENGTH) return;
      entries.push({ number: marker.number, text: body, start: marker.index, marker: marker.marker });
    });
    return entries;
  }

  const m = LEADING_NUMBER.exec(text);
  if (!m) return [];
  const number = Number(m[1] ?? m[2]);
  const body = text.slice(m[0].length).trim();
  if (!Number.isFinite(number) || number < 1 || body.length < MIN_ENTRY_LENGTH) return [];
  return [{ number, text: body, start: 0, marker: m[0].trim() }];
}

/**
 * The bibliography, wherever it is and however it is laid out.
 *
 * With a heading, everything numbered after it counts. Without one, the tail of
 * the document is walked backwards for as long as the paragraphs keep parsing as
 * entries — two entries is enough to call it a list, and one is not, because a
 * single numbered paragraph is usually a step in a procedure.
 */
export function parseBibliography(paragraphs: readonly string[]): BibliographyEntry[] {
  let headingAt = -1;
  paragraphs.forEach((text, i) => {
    if (HEADING.test(text)) headingAt = i;
  });

  const from = (start: number): BibliographyEntry[] => {
    const entries: BibliographyEntry[] = [];
    for (let i = start; i < paragraphs.length; i += 1) {
      for (const entry of splitEntries(paragraphs[i]!)) entries.push({ ...entry, paragraphIndex: i });
    }
    return entries;
  };

  if (headingAt >= 0) {
    const entries = from(headingAt + 1);
    if (entries.length > 0) return entries;
  }

  let start = paragraphs.length;
  for (let i = paragraphs.length - 1; i >= 0; i -= 1) {
    const text = paragraphs[i]!;
    if (text.trim().length === 0) continue; // blank lines inside the list
    if (splitEntries(text).length === 0) break;
    start = i;
  }

  const entries = from(start);
  return entries.length >= 2 ? entries : [];
}

/**
 * A one-line description of an entry, for a pane that is 380 px wide.
 *
 * The journal, year and volume are what identify a paper at a glance; the full
 * author list is what makes an entry unreadable at this width. So when the
 * 「誌名 年, 巻,」 shape is there, the line is built from it, and the first author
 * is kept as the thing people actually remember the paper by.
 */
/** 「2019, 58」 — the year and the volume, which is where the journal name stops. */
const YEAR_VOLUME = /(?:19|20)\d{2}\s*,\s*\d+/u;
const FIRST_AUTHOR = /^([A-Z][A-Za-z'’-]+(?:,\s*[A-Z]\.(?:\s*[A-Z]\.)*)?|(?:[A-Z]\.\s*)+[A-Z][A-Za-z'’-]+)/u;

/** Where an author list stops and a journal begins. */
const ET_AL = /\bet\s+al\.?\s*/iu;

/**
 * Drops a last author's initial that got swept into the journal name.
 *
 * 「Smith, J. A.; Brown, K. Chem. Commun. 2020, 56」 — the journal starts at
 * 「Chem.」, but 「K.」 sits right in front of it and looks exactly like the first
 * token of a name.
 *
 * Which it is depends on the entry's own convention, and the *first* author
 * gives that away. 「Smith, J. A.」 puts the surname first, so a lone initial
 * before the journal belongs to the last author. 「M. Ito」 puts initials first,
 * so nothing separates them from the journal — and 「J. Phys. Chem. A」 keeps its
 * J. Getting this wrong either way is a one-token error in a display line whose
 * full text is a hover away.
 */
const LEADING_INITIAL = /^[A-Z]\.\s+(?=[A-Z])/u;

/**
 * One line naming the paper: 「Osaka ら、J. Mater. Chem. C 2020, 8」.
 *
 * The journal is whatever sits between the authors and the year. Finding it by
 * pattern alone does not work — 「J. Kido et al. Adv. Mater. 2015」 is all capitals
 * and periods from end to end, so any 「capitalised words before a year」 rule
 * swallows the author too. So the authors are cut off explicitly: at 「et al.」
 * when it is there, and otherwise at the last comma or semicolon, which is where
 * the final author's name ends.
 */
export function describeEntry(entry: BibliographyEntry): string {
  const yearVolume = YEAR_VOLUME.exec(entry.text);
  if (!yearVolume) return entry.text;

  const author = FIRST_AUTHOR.exec(entry.text)?.[1] ?? "";
  const surnameFirst = author.includes(",");

  const head = entry.text.slice(0, yearVolume.index);
  const etAl = ET_AL.exec(head);
  let journal = etAl ? head.slice(etAl.index + etAl[0].length) : head.slice(lastAuthorEnd(head));
  journal = journal.replace(/^[\s,;]+/u, "").replace(/[\s,;]+$/u, "");
  if (!etAl && surnameFirst) journal = journal.replace(LEADING_INITIAL, "");
  if (journal.length === 0) return entry.text;

  const surname = surnameFirst ? author.slice(0, author.indexOf(",")) : author.split(/\s+/u).pop() ?? "";
  return `${surname ? `${surname} ら、` : ""}${journal} ${yearVolume[0].replace(/\s*,\s*/u, ", ")}`;
}

/** Index just past the last author separator, or 0 when there is none. */
function lastAuthorEnd(head: string): number {
  const at = Math.max(head.lastIndexOf(","), head.lastIndexOf(";"));
  return at < 0 ? 0 : at + 1;
}

// --- 本文の引用番号との突き合わせ ------------------------------------------

const BRACKET_CITATION = /\[\s*\d+(?:\s*[,、–—−-]\s*\d+)*\s*\]/gu;

/** True when the paragraph is inside the bibliography rather than the body. */
export function bibliographyParagraphs(entries: readonly BibliographyEntry[]): ReadonlySet<number> {
  return new Set(entries.map((entry) => entry.paragraphIndex));
}

/**
 * Citation markers in the body only.
 *
 * A bibliography entry may itself open with `[1]`, and counting that as a
 * citation would make every reference look cited exactly once even when nothing
 * in the text points at it — which is the case this whole module exists to find.
 */
export function bodyCitations(
  paragraphs: readonly string[],
  skip: ReadonlySet<number>,
): Array<{ paragraphIndex: number; start: number; text: string }> {
  const hits: Array<{ paragraphIndex: number; start: number; text: string }> = [];
  paragraphs.forEach((text, paragraphIndex) => {
    if (skip.has(paragraphIndex)) return;
    for (const m of matchAll(BRACKET_CITATION, text)) {
      hits.push({ paragraphIndex, start: m.index, text: m[0] });
    }
  });
  return hits;
}
