// --- 化合物・文献・フォントの一覧 ------------------------------------------
//
// Views that answer 「この原稿には何が入っているのか」 rather than 「どこが間違って
// いるのか」. They share a shape: scan, list, click a row to jump.

/**
 * Which occurrence a row will jump to next, keyed by view and label.
 *
 * A compound mentioned eleven times is exactly the one worth walking through,
 * and a button that always jumped to the first mention would make that
 * impossible. The cursor wraps, so the row keeps working forever.
 */
const jumpCursor = new Map<string, number>();

/** Page numbers for the last list, when the host could supply them. */
let pageOf = new Map<number, number>();

/** 「3ページ 12段落」 or just 「12段落」 where the host has no page API. */
function where(paragraphIndex: number): string {
  const page = pageOf.get(paragraphIndex);
  return page === undefined ? `${paragraphIndex + 1}段落` : `${page}ページ ${paragraphIndex + 1}段落`;
}

/** Selects one occurrence and says where it landed. */
async function reveal(
  label: string,
  occurrence: actions.Occurrence,
  index: number,
  total: number,
): Promise<void> {
  const ok = await actions.revealSpan(
    { paragraphIndex: occurrence.paragraphIndex, start: occurrence.start, matched: occurrence.text },
    options(),
  );
  setStatus(
    ok
      ? `「${label}」${index + 1}/${total} 件目（${where(occurrence.paragraphIndex)}）を選択しました。`
      : "該当箇所が見つかりませんでした。文書が変わっている場合は一覧を作り直してください。",
  );
}

/** The label button: each press walks one step further through the occurrences. */
function jumpTo(key: string, label: string, occurrences: readonly actions.Occurrence[]): () => void {
  return run(async () => {
    if (occurrences.length === 0) return;
    const at = (jumpCursor.get(key) ?? 0) % occurrences.length;
    jumpCursor.set(key, at + 1);
    await reveal(label, occurrences[at]!, at, occurrences.length);
  });
}

/**
 * 出現箇所を 1 つずつ押せる行。
 *
 * The locations used to be plain text, which meant the only way to reach the
 * fourth mention of a compound was to press the label three times and watch the
 * cursor go by. Each place is its own button now, so 「7ページ 31段落」 is a
 * destination rather than a description.
 */
const PLACES_SHOWN = 8;

function placesRow(label: string, occurrences: readonly actions.Occurrence[]): HTMLElement {
  const row = document.createElement("p");
  row.className = "finding-quote places";
  occurrences.slice(0, PLACES_SHOWN).forEach((occurrence, i) => {
    if (i > 0) row.appendChild(document.createTextNode(" / "));
    const place = document.createElement("button");
    place.type = "button";
    place.className = "place";
    place.textContent = where(occurrence.paragraphIndex);
    place.title = `${label} の ${i + 1} 件目へ移動`;
    place.onclick = run(() => reveal(label, occurrence, i, occurrences.length));
    row.appendChild(place);
  });
  if (occurrences.length > PLACES_SHOWN) {
    row.appendChild(document.createTextNode(` ほか ${occurrences.length - PLACES_SHOWN} 件`));
  }
  return row;
}

/**
 * 化合物番号の一覧。
 *
 * A table rather than the chips it used to be: with the page and paragraph of
 * every mention there is too much to fit on one line, and 「何ページの何段落」 is
 * the thing that makes the list usable without clicking each row.
 */
function renderCompounds(items: readonly actions.InventoryItem[]): void {
  const container = byId("compounds");
  container.innerHTML = "";
  if (items.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent =
      "化合物番号は見つかりませんでした（太字の番号、「化合物 5」のように語を伴うもの、5a のような系列ラベルを数えます）。";
    container.appendChild(empty);
    return;
  }

  for (const item of items) {
    const row = document.createElement("div");
    row.className = `finding ${item.occurrences.length === 1 ? "severity-confirm" : "severity-note"}`;

    const head = document.createElement("div");
    head.className = "finding-head";
    const label = document.createElement("button");
    label.type = "button";
    label.className = "inventory-label badge";
    label.textContent = item.label;
    label.onclick = jumpTo(`compounds:${item.label}`, item.label, item.occurrences);
    const count = document.createElement("span");
    count.className = "severity";
    count.textContent = `${item.occurrences.length} 件`;
    head.append(label, count);

    row.append(head, placesRow(item.label, item.occurrences));
    container.appendChild(row);
  }
}

/** 文献番号の一覧。番号だけでなく、末尾の文献リストから拾った書誌も出す。 */
function renderReferences(report: actions.LabelReport): void {
  const container = byId("references");
  container.innerHTML = "";
  if (report.references.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent = "文献番号は見つかりませんでした。";
    container.appendChild(empty);
    return;
  }

  for (const item of report.references) {
    const missing = item.entry === undefined;
    const uncited = item.citations.length === 0;
    const row = document.createElement("div");
    row.className = `finding ${missing || uncited ? "severity-fix" : "severity-note"}`;

    const head = document.createElement("div");
    head.className = "finding-head";
    const label = document.createElement("button");
    label.type = "button";
    label.className = "inventory-label badge";
    label.textContent = `[${item.number}]`;
    label.onclick = jumpTo(`references:${item.number}`, `[${item.number}]`, item.citations);
    const count = document.createElement("span");
    count.className = "severity";
    count.textContent = uncited ? "本文に引用なし" : `${item.citations.length} 回`;
    head.append(label, count);
    row.appendChild(head);

    if (item.entry) {
      const summary = document.createElement("p");
      summary.className = "finding-message reference-entry";
      summary.textContent = item.entry.summary;
      summary.title = item.entry.full;
      row.appendChild(summary);

      const jump = document.createElement("div");
      jump.className = "row compact";
      const target = item.entry.at;
      jump.appendChild(
        button(`文献リストへ（${where(target.paragraphIndex)}）`, run(() =>
          reveal(`[${item.number}] の文献`, target, 0, 1),
        )),
      );
      row.appendChild(jump);
    } else {
      const warning = document.createElement("p");
      warning.className = "finding-message";
      warning.textContent = report.hasBibliography
        ? "文献リストに該当する項目がありません。"
        : "文献リストが見つからないため、書誌は表示できません。";
      row.appendChild(warning);
    }

    if (item.citations.length > 0) {
      row.appendChild(placesRow(`[${item.number}]`, item.citations));
    }

    container.appendChild(row);
  }
}

/** Fetches page numbers for the paragraphs a list points at, best effort. */
async function loadPages(paragraphIndices: readonly number[]): Promise<void> {
  pageOf = await actions.paragraphPages([...new Set(paragraphIndices)], options());
}

async function listCompounds(): Promise<void> {
  setStatus("化合物番号を集めています…");
  showView("compounds");
  const { compounds } = await actions.listLabels(options());
  await loadPages(compounds.flatMap((item) => item.occurrences.map((o) => o.paragraphIndex)));
  renderCompounds(compounds);

  const once = compounds.filter((item) => item.occurrences.length === 1).length;
  setStatus(
    compounds.length === 0
      ? "化合物番号は見つかりませんでした。"
      : `${compounds.length} 種類の化合物番号。${once > 0 ? `うち ${once} 種類は 1 回しか出てきません。` : ""}`,
  );
}

async function listReferences(): Promise<void> {
  setStatus("文献番号を集めています…");
  showView("references");
  const report = await actions.listLabels(options());
  await loadPages([
    ...report.references.flatMap((item) => item.citations.map((o) => o.paragraphIndex)),
    ...report.references.flatMap((item) => (item.entry ? [item.entry.at.paragraphIndex] : [])),
  ]);
  renderReferences(report);

  const notes: string[] = [];
  if (!report.hasBibliography) notes.push("末尾の文献リストは見つかりませんでした");
  if (report.missingEntries.length > 0) {
    notes.push(`文献リストにない番号：${report.missingEntries.join("、")}`);
  }
  if (report.uncited.length > 0) notes.push(`本文が引用していない番号：${report.uncited.join("、")}`);
  setStatus(
    report.references.length === 0
      ? "文献番号は見つかりませんでした。"
      : `${report.references.length} 件の文献番号。${notes.length > 0 ? notes.join("／") + "。" : "対応に漏れはありません。"}`,
  );
}

/**
 * The target offered first, and so the one selected unless the user picks
 * another — it is what a submitted manuscript's Latin text is set in, and this
 * button exists mostly to put a draft back to it.
 */
const DEFAULT_FONT_TARGET = "Times New Roman";

/** Fonts always worth offering as a target, on top of the ones in use. */
const COMMON_FONTS: readonly string[] = [
  "Arial", "Helvetica", "Calibri", "Cambria",
  "ＭＳ 明朝", "ＭＳ ゴシック", "游明朝", "游ゴシック", "Hiragino Mincho ProN", "Hiragino Kaku Gothic ProN",
];

/**
 * Lists the fonts in use, each with a target and a 置換 button.
 *
 * `note` carries the result of a replacement through the refresh that follows
 * it. Without it the list would rebuild and the status line would go back to
 * 「N 種類のフォントが使われています」, quietly swallowing the only confirmation the
 * user gets that anything changed.
 */
async function replaceFonts(note?: string): Promise<void> {
  if (note === undefined) setStatus("使われているフォントを調べています…");
  showView("fonts");
  const usages = await actions.listFonts(options());

  const container = byId("font-usage");
  container.innerHTML = "";
  if (usages.length === 0) {
    const empty = document.createElement("p");
    empty.className = "lead";
    empty.textContent = "フォントを読み取れませんでした。";
    container.appendChild(empty);
    setStatus("フォントを読み取れませんでした。");
    return;
  }

  // Times New Roman first, so it is the selected option in every row without
  // any per-row fiddling — a `<select>` shows its first option by default.
  const targets = [
    ...new Set([DEFAULT_FONT_TARGET, ...usages.map((usage) => usage.name), ...COMMON_FONTS, prefs.bodyFont]),
  ];

  for (const usage of usages) {
    const row = document.createElement("div");
    row.className = "finding severity-note";

    const head = document.createElement("div");
    head.className = "finding-head";
    const badge = document.createElement("span");
    badge.className = "badge";
    badge.textContent = usage.name;
    const count = document.createElement("span");
    count.className = "severity";
    count.textContent = `${usage.ranges} 箇所${usage.japanese ? "・和文" : ""}`;
    head.append(badge, count);

    const sample = document.createElement("p");
    sample.className = "finding-quote";
    sample.textContent = usage.sample ? `例: ${truncate(usage.sample, 30)}` : "";

    const controls = document.createElement("div");
    controls.className = "row compact";

    const select = document.createElement("select");
    for (const target of targets) {
      if (target === usage.name) continue;
      const option = document.createElement("option");
      option.value = target;
      option.textContent = target;
      select.appendChild(option);
    }

    const apply = button(
      "置換",
      run(async () => {
        const to = select.value;
        if (!to) return;
        setStatus(`「${usage.name}」を「${to}」に置換しています…`);
        const n = await actions.replaceFontEverywhere(usage.name, to, options());
        if (n === 0) {
          setStatus(`「${usage.name}」の箇所が見つかりませんでした。一覧を作り直してください。`);
          return;
        }
        await replaceFonts(`「${usage.name}」の ${n} 箇所を「${to}」に置換しました（取り消しは ⌘Z）。`);
      }),
      "primary",
    );

    controls.append(select, apply);
    row.append(head, sample, controls);
    container.appendChild(row);
  }

  setStatus(note ?? `${usages.length} 種類のフォントが使われています。`);
}

/** Records painted spans so the clear command knows what is the add-in's to undo. */
function remember(findings: readonly Finding[]): void {
  const seen = new Set(painted.map(ignoreKey));
  painted = [...painted, ...findings.filter((f) => !seen.has(ignoreKey(f)))];
}

async function clearHighlights(): Promise<void> {
  setStatus("このアドインが塗った箇所を消去中…");
  // With no record of what was painted — a pane reopened since — fall back to
  // the current review's spans and to every space, which is the widest set this
  // add-in could have painted.
  const blind = painted.length === 0;
  const n = await actions.clearHighlights(options(), {
    findings: blind ? selected() : painted,
    spaces: paintedSpaces || blind,
  });
  painted = [];
  paintedSpaces = false;
  setStatus(
    n === 0
      ? "消せるハイライトが見つかりませんでした。手で塗ったマーカーごと消すには、リボンの［ハイライトを全て削除］を使ってください。"
      : `${n} 箇所のハイライトを消去しました（手で塗ったマーカーは残しています）。`,
  );
}
