/* global Word */
/**
 * DOM-independent Word operations shared by the task pane (src/taskpane) and the
 * ribbon command runtime (src/commands). Each function opens its own `Word.run`
 * and returns a plain data summary; callers decide how to present it (pane list
 * vs. ribbon notification).
 */
import { review, type ReviewOptions } from "../core/engine.ts";
import { HIGHLIGHT_PALETTE } from "../core/palette.ts";
import { CATEGORIES, type Category, type Finding, type RuleSettings } from "../core/types.ts";
import { compoundLabels } from "../core/labels.ts";
import {
  buildInventory,
  citedNumbers,
  compoundMentions,
  type CompoundMention,
  type InventoryItem,
  type Occurrence,
} from "../core/inventory.ts";
import {
  bibliographyParagraphs,
  bodyCitations,
  describeEntry,
  parseBibliography,
} from "../core/references.ts";
import { locateFindings, type Locatable } from "./locate.ts";
import { replaceFont, scanFonts, type FontUsage } from "./fontScan.ts";
import { RULE_CATALOG, titleFor } from "./ruleCatalog.ts";
import {
  applyFormatFix,
  applyParagraphFix,
  buildFontInventory,
  dropSuperscriptCitations,
  isFormatCheckId,
  isParagraphCheckId,
  preferredLatinFont,
  runFormatChecks,
  runParagraphChecks,
  type FontInventory,
} from "./formatChecks.ts";

/** Highlight color used by the ribbon's 「全スペース強調」 command. */
export const SPACING_HIGHLIGHT = "#80DEEA"; // cyan

/** Options normally taken from the task-pane settings; the ribbon uses defaults. */
export interface ActionOptions {
  /** Restrict to the current selection instead of the whole document body. */
  readonly selectionOnly: boolean;
  /** Latin font used when a formatting fix has to name one. */
  readonly bodyFont: string;
  /** Record edits as tracked changes. */
  readonly trackChanges: boolean;
  /** Thresholds and language passed through to the engine. */
  readonly reviewOptions?: ReviewOptions;
  /** Rules switched off in 「ルール設定」 — text rules and formatting checks alike. */
  readonly disabledRules?: readonly string[];
  /** Marker colors changed in 「設定」; a category left out keeps its checklist color. */
  readonly markerColors?: Readonly<Partial<Record<Category, string>>>;
  /** Color for 「全スペース強調」; defaults to `SPACING_HIGHLIGHT`. */
  readonly spaceColor?: string;
}

export const DEFAULT_OPTIONS: ActionOptions = {
  selectionOnly: false,
  bodyFont: "Times New Roman",
  trackChanges: false,
};

/** The color a category is painted with under these options. */
export function highlightFor(category: Category, opts: ActionOptions): string {
  return opts.markerColors?.[category] ?? CATEGORIES[category].highlight;
}

function scopeOf(context: Word.RequestContext, selectionOnly: boolean): Word.Range | Word.Body {
  return selectionOnly ? context.document.getSelection() : context.document.body;
}

/** Paints every space in the document, so stray ones are visible at a glance. */
export async function highlightAllSpaces(opts: ActionOptions): Promise<number> {
  return Word.run(async (context) => {
    const scope = scopeOf(context, opts.selectionOnly);
    const color = opts.spaceColor ?? SPACING_HIGHLIGHT;
    let highlighted = 0;
    for (const space of [" ", "\u3000"]) {
      const results = scope.search(space, { matchCase: true, matchWildcards: false });
      results.load("items");
      await context.sync();
      for (const item of results.items) {
        item.font.highlightColor = color;
        highlighted += 1;
      }
    }
    await context.sync();
    return highlighted;
  });
}

// --- ハイライトの片付け ----------------------------------------------------
//
// Clearing used to null the highlight of the whole body, which also erased the
// marks a co-author or the writer had put there by hand — and Word offers no way
// to tell those apart after the fact. So the add-in now undoes only what it did:
// the spans it painted, and only while they still carry a color it paints with.

/** Word answers with a name for its own palette entries, not always a hex. */
const HIGHLIGHT_NAMES: Readonly<Record<string, string>> = Object.freeze({
  yellow: "#FFFF00",
  brightgreen: "#00FF00",
  green: "#008000",
  turquoise: "#00FFFF",
  teal: "#008080",
  pink: "#FF00FF",
  magenta: "#FF00FF",
  blue: "#0000FF",
  gray25: "#C0C0C0",
  gray50: "#808080",
});

/** Both spellings reduced to `#RRGGBB`, or "" when there is no highlight. */
function normalizeHighlight(value: unknown): string {
  if (typeof value !== "string" || value.length === 0) return "";
  const lower = value.toLowerCase();
  if (HIGHLIGHT_NAMES[lower]) return HIGHLIGHT_NAMES[lower]!;
  return lower.startsWith("#") ? `#${lower.slice(1).toUpperCase()}` : `#${lower.toUpperCase()}`;
}

/** Every color this add-in is capable of painting with. */
const TOOL_COLORS: ReadonlySet<string> = new Set([
  ...HIGHLIGHT_PALETTE.map((color) => normalizeHighlight(color.value)),
  ...Object.values(CATEGORIES).map((info) => normalizeHighlight(info.highlight)),
  normalizeHighlight(SPACING_HIGHLIGHT),
]);

/** What a clear pass should undo. */
export interface ClearTarget {
  /** Spans painted by 「マーカーで塗る」. */
  readonly findings?: readonly Finding[];
  /** Spaces painted by 「スペース強調」. */
  readonly spaces?: boolean;
}

/**
 * Removes the highlight from the given spans, leaving every other mark in the
 * document alone. A span whose color is not one this add-in paints with is
 * skipped: it belongs to somebody else.
 */
export async function clearHighlights(opts: ActionOptions, target: ClearTarget): Promise<number> {
  const findings = target.findings ?? [];
  if (findings.length === 0 && !target.spaces) return 0;

  return Word.run(async (context) => {
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);
    const candidates: Word.Range[] = [];

    if (findings.length > 0) {
      const located = await locateFindings(context, paragraphs, texts, findings);
      candidates.push(...located.map((item) => item.range));
    }

    if (target.spaces) {
      const scope = scopeOf(context, opts.selectionOnly);
      const batches = [" ", "　"].map((space) => {
        const results = scope.search(space, { matchCase: true, matchWildcards: false });
        results.load("items");
        return results;
      });
      await context.sync();
      for (const batch of batches) candidates.push(...batch.items);
    }

    if (candidates.length === 0) return 0;
    for (const range of candidates) range.font.load("highlightColor");
    await context.sync();

    let cleared = 0;
    for (const range of candidates) {
      if (!TOOL_COLORS.has(normalizeHighlight(range.font.highlightColor))) continue;
      range.font.highlightColor = null as unknown as string;
      cleared += 1;
    }
    await context.sync();
    return cleared;
  });
}

/**
 * The old blunt instrument: wipe every highlight in scope, whoever made it.
 *
 * Kept because a document that has been marked up by several people sometimes
 * does need a reset, but it is no longer what the ribbon button does — the pane
 * asks for it by name.
 */
export async function clearAllHighlights(opts: ActionOptions): Promise<void> {
  return Word.run(async (context) => {
    const scope = scopeOf(context, opts.selectionOnly);
    if ("font" in scope) {
      (scope as Word.Body).font.highlightColor = null as unknown as string;
    }
    await context.sync();
  });
}

// --- 添削チェックリストの一括レビュー -------------------------------------

/** Loads the paragraphs in scope together with their text. */
async function loadParagraphs(
  context: Word.RequestContext,
  selectionOnly: boolean,
): Promise<{ paragraphs: Word.Paragraph[]; texts: string[] }> {
  const scope = scopeOf(context, selectionOnly);
  const collection = scope.paragraphs;
  collection.load("items/text");
  await context.sync();
  const paragraphs = collection.items;
  return { paragraphs, texts: paragraphs.map((p) => p.text) };
}

export interface ReviewResult {
  readonly findings: readonly Finding[];
  readonly fontInventory: FontInventory;
  readonly paragraphCount: number;
}

/**
 * Runs the whole checklist: the text rules from the engine plus the formatting
 * checks that need Word. Findings come back in document order.
 */
export async function reviewDocument(opts: ActionOptions): Promise<ReviewResult> {
  return Word.run(async (context) => {
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);

    const disabled = new Set(opts.disabledRules ?? []);
    const rawTextFindings = review(texts, {
      ...(opts.reviewOptions ?? {}),
      disabledRules: [...disabled],
    });
    // Superscript digits are citation numbers, which the text rules cannot see.
    const textFindings = await dropSuperscriptCitations(context, paragraphs, texts, rawTextFindings);
    const formatFindings = await runFormatChecks(context, paragraphs, texts, disabled);
    const paragraphFindings = await runParagraphChecks(context, paragraphs, texts, disabled);
    const fontInventory = await buildFontInventory(context, paragraphs, texts);

    const findings = [...textFindings, ...formatFindings, ...paragraphFindings].sort(
      (a, b) =>
        a.paragraphIndex - b.paragraphIndex ||
        a.start - b.start ||
        a.ruleId.localeCompare(b.ruleId),
    );

    return { findings, fontInventory, paragraphCount: texts.length };
  });
}

/**
 * Paints each finding in its checklist marker color (ピンク/青/黄緑/黄), so the
 * document ends up looking like one marked up by hand.
 */
export async function highlightFindings(
  findings: readonly Finding[],
  opts: ActionOptions,
): Promise<number> {
  if (findings.length === 0) return 0;
  return Word.run(async (context) => {
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);
    const located = await locateFindings(context, paragraphs, texts, findings);
    for (const { finding, range } of located) {
      range.font.highlightColor = highlightFor(finding.category, opts);
    }
    await context.sync();
    return located.length;
  });
}

/**
 * Attaches each finding to the document as a Word comment.
 *
 * A highlight says "look here"; a comment says what is wrong, in the margin,
 * where a supervisor's own remarks go. The author can reply to it or resolve it
 * with Word's own review tools, which is the workflow the checklist describes.
 */
export async function commentFindings(
  findings: readonly Finding[],
  opts: ActionOptions,
): Promise<number> {
  if (findings.length === 0) return 0;
  return Word.run(async (context) => {
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);
    const located = await locateFindings(context, paragraphs, texts, findings);
    if (located.length === 0) return 0;

    // Comments arrived in WordApi 1.4; older builds silently lack the method.
    if (typeof located[0]!.range.insertComment !== "function") {
      throw new Error("この Word ではコメントを挿入できません（Word 2021 / Microsoft 365 が必要です）。");
    }

    for (const { finding, range } of located) range.insertComment(commentText(finding));
    await context.sync();
    return located.length;
  });
}

/** The text of one review comment: which check fired, then what it says. */
export function commentText(finding: Finding): string {
  return `【${titleFor(finding.ruleId)}】${finding.message}`;
}

// --- コメントの片付け ------------------------------------------------------
//
// The same principle as clearing highlights: a document's comments are mostly
// the supervisor's, and losing those would be worse than leaving the add-in's
// behind. So a comment is deleted only when it is recognisably one this add-in
// wrote — 【ルール名】 followed by the message — and the rule name has to be one
// this build actually has. Nothing else in the margin is touched.

/** Rule titles this build can have written into a comment. */
const COMMENT_TITLES: ReadonlySet<string> = new Set(RULE_CATALOG.map((item) => item.title));

/** True when a comment's text has the shape `commentText` gives its comments. */
export function isToolComment(text: unknown): boolean {
  if (typeof text !== "string") return false;
  const match = /^【([^】]+)】/u.exec(text.trimStart());
  return match !== null && COMMENT_TITLES.has(match[1]!);
}

/** Word gained comments in WordApi 1.4; older builds have no such method. */
interface CommentScope {
  getComments?: () => Word.CommentCollection;
}

/**
 * Deletes the comments this add-in inserted, leaving everybody else's alone.
 *
 * Returns how many went. Word's undo (⌘Z) puts them back, so this is as
 * reversible as any other edit the add-in makes.
 */
export async function clearComments(opts: ActionOptions): Promise<number> {
  return Word.run(async (context) => {
    const scope = scopeOf(context, opts.selectionOnly) as unknown as CommentScope;
    if (typeof scope.getComments !== "function") {
      throw new Error("この Word ではコメントを操作できません（Word 2021 / Microsoft 365 が必要です）。");
    }
    const comments = scope.getComments();
    comments.load("items/content");
    await context.sync();

    const mine = comments.items.filter((comment) => isToolComment(comment.content));
    for (const comment of mine) comment.delete();
    await context.sync();
    return mine.length;
  });
}

/**
 * The blunt instrument for comments, matching `clearAllHighlights`.
 *
 * Deletes every comment in scope, the supervisor's included. Nothing about a
 * comment says who wrote it in a way this add-in should act on, so this is not a
 * smarter version of `clearComments` — it is the deliberate, destructive one,
 * and the ribbon labels have to keep the two apart. ⌘Z is the only way back.
 */
export async function clearAllComments(opts: ActionOptions): Promise<number> {
  return Word.run(async (context) => {
    const scope = scopeOf(context, opts.selectionOnly) as unknown as CommentScope;
    if (typeof scope.getComments !== "function") {
      throw new Error("この Word ではコメントを操作できません（Word 2021 / Microsoft 365 が必要です）。");
    }
    const comments = scope.getComments();
    comments.load("items");
    await context.sync();

    const all = [...comments.items];
    for (const comment of all) comment.delete();
    await context.sync();
    return all.length;
  });
}

/** Selects a single span and scrolls the document to it. */
export async function revealSpan(span: Locatable, opts: ActionOptions): Promise<boolean> {
  return Word.run(async (context) => {
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);
    const located = await locateFindings(context, paragraphs, texts, [span]);
    const target = located[0];
    if (!target) return false;
    target.range.select();
    await context.sync();
    return true;
  });
}

/** Selects a single finding and scrolls the document to it. */
export async function revealFinding(finding: Finding, opts: ActionOptions): Promise<boolean> {
  return revealSpan(finding, opts);
}

// --- 文書の中身を数え上げる ------------------------------------------------
//
// 化合物・文献・フォントの一覧。どれも指摘ではなく、読む前に把握しておきたい
// 事実で、そのために文書を一度走査する。

/**
 * Keeps the bold proposals that really are bold, and drops the rest.
 *
 * Boldness is the author's own statement that a number is a compound, so it is
 * the strongest signal there is — but it is only readable through Word, which is
 * why `compoundMentions` proposes and this disposes.
 */
async function confirmBold(
  context: Word.RequestContext,
  paragraphs: Word.Paragraph[],
  texts: readonly string[],
  mentions: readonly CompoundMention[],
): Promise<CompoundMention[]> {
  const settled = mentions.filter((mention) => mention.evidence !== "bold");
  const proposals = mentions.filter((mention) => mention.evidence === "bold");
  if (proposals.length === 0) return settled;

  const located = await locateFindings(
    context,
    paragraphs,
    texts,
    proposals.map((mention) => ({
      paragraphIndex: mention.at.paragraphIndex,
      start: mention.at.start,
      matched: mention.at.text,
      mention,
    })),
  );
  for (const { range } of located) range.font.load("bold");
  await context.sync();

  return [...settled, ...located.filter((item) => item.range.font.bold).map((item) => item.finding.mention)];
}

/** One reference number: where the body cites it, and what the entry says. */
export interface ReferenceRow {
  readonly number: number;
  readonly citations: readonly Occurrence[];
  /** The bibliography entry, when the document has one for this number. */
  readonly entry?: {
    /** Where the entry's own 「[2]」 marker sits — a whole list can share one paragraph. */
    readonly at: Occurrence;
    /** One line: 「Tanaka ら、J. Am. Chem. Soc. 2019, 141」. */
    readonly summary: string;
    readonly full: string;
  };
}

export interface LabelReport {
  readonly compounds: InventoryItem[];
  readonly references: ReferenceRow[];
  /** Cited in the text but absent from the bibliography. */
  readonly missingEntries: number[];
  /** In the bibliography but never cited. */
  readonly uncited: number[];
  /** True when a bibliography was found at all. */
  readonly hasBibliography: boolean;
}

/** 化合物番号と文献番号の一覧。太字の確認のためだけに Word を読む。 */
export async function listLabels(opts: ActionOptions): Promise<LabelReport> {
  return Word.run(async (context) => {
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);

    const bibliography = parseBibliography(texts);
    const inList = bibliographyParagraphs(bibliography);

    const mentions = compoundMentions(texts, compoundLabels(texts), inList);
    const compounds = buildInventory(await confirmBold(context, paragraphs, texts, mentions));

    const cited = new Map<number, Occurrence[]>();
    for (const hit of bodyCitations(texts, inList)) {
      for (const number of citedNumbers(hit.text)) {
        if (!cited.has(number)) cited.set(number, []);
        cited.get(number)!.push(hit);
      }
    }

    const byNumber = new Map(bibliography.map((entry) => [entry.number, entry]));
    const numbers = [...new Set([...cited.keys(), ...byNumber.keys()])].sort((a, b) => a - b);

    const references: ReferenceRow[] = numbers.map((number) => {
      const entry = byNumber.get(number);
      return {
        number,
        citations: cited.get(number) ?? [],
        ...(entry === undefined
          ? {}
          : {
              entry: {
                at: {
                  paragraphIndex: entry.paragraphIndex,
                  start: entry.start,
                  text: entry.marker,
                },
                summary: describeEntry(entry),
                full: entry.text,
              },
            }),
      };
    });

    return {
      compounds,
      references,
      missingEntries: numbers.filter((n) => cited.has(n) && !byNumber.has(n)),
      uncited: numbers.filter((n) => byNumber.has(n) && !cited.has(n)),
      hasBibliography: bibliography.length > 0,
    };
  });
}

/**
 * Page numbers for the given paragraphs, or an empty map.
 *
 * `Range.pages` is WordApiDesktop 1.2 — Word on the desktop, recent builds only.
 * It runs in its own `Word.run` so that a host without it fails here and nowhere
 * else: the compound list is still worth showing with paragraph numbers alone.
 */
export async function paragraphPages(
  indices: readonly number[],
  opts: ActionOptions,
): Promise<Map<number, number>> {
  const pages = new Map<number, number>();
  if (indices.length === 0) return pages;
  try {
    return await Word.run(async (context) => {
      const { paragraphs } = await loadParagraphs(context, opts.selectionOnly);
      const pending: Array<{ index: number; collection: Word.PageCollection }> = [];
      for (const index of indices) {
        const paragraph = paragraphs[index];
        if (!paragraph) continue;
        const collection = paragraph.getRange().pages;
        collection.load("items/index");
        pending.push({ index, collection });
      }
      if (pending.length === 0) return pages;
      await context.sync();
      for (const { index, collection } of pending) {
        const page = collection.items[0];
        if (page) pages.set(index, page.index);
      }
      return pages;
    });
  } catch {
    return pages; // 古い Word・Web 版。段落番号だけで出す。
  }
}

/** The fonts the document uses, for 「フォントを置換」. */
export async function listFonts(opts: ActionOptions): Promise<FontUsage[]> {
  return Word.run(async (context) => {
    const { paragraphs } = await loadParagraphs(context, opts.selectionOnly);
    return scanFonts(context, paragraphs);
  });
}

/** Sets every range in `from` to `to`, returning how many changed. */
export async function replaceFontEverywhere(
  from: string,
  to: string,
  opts: ActionOptions,
): Promise<number> {
  return Word.run(async (context) => {
    if (opts.trackChanges) {
      context.document.changeTrackingMode = Word.ChangeTrackingMode.trackAll;
    }
    const { paragraphs } = await loadParagraphs(context, opts.selectionOnly);
    return replaceFont(context, paragraphs, from, to);
  });
}


export interface ApplyResult {
  readonly applied: number;
  /** Findings that could no longer be located, usually because text shifted. */
  readonly skipped: number;
}

/**
 * Applies the replacements (and formatting fixes) for the given findings.
 *
 * Every finding is located before anything is written, so the offsets they were
 * computed against are still valid. A finding whose text has already changed is
 * skipped rather than applied to the wrong span.
 */
export async function applyFindings(
  findings: readonly Finding[],
  opts: ActionOptions,
): Promise<ApplyResult> {
  // 「キャプションは中央揃えにしない」 sets a property of the paragraph, so it needs
  // no range at all and takes a path of its own.
  const paragraphFixes = findings.filter((f) => isParagraphCheckId(f.ruleId));
  const requested = findings.filter(
    (f) => !isParagraphCheckId(f.ruleId) && (f.replacement !== undefined || isFormatCheckId(f.ruleId)),
  );
  const actionable = orderForApply(requested);
  if (actionable.length === 0 && paragraphFixes.length === 0) return { applied: 0, skipped: 0 };

  return Word.run(async (context) => {
    if (opts.trackChanges) {
      context.document.changeTrackingMode = Word.ChangeTrackingMode.trackAll;
    }
    const { paragraphs, texts } = await loadParagraphs(context, opts.selectionOnly);
    const located = await locateFindings(context, paragraphs, texts, actionable);

    let applied = 0;
    for (const item of paragraphFixes) {
      const paragraph = paragraphs[item.paragraphIndex];
      if (paragraph && applyParagraphFix(item.ruleId, paragraph)) applied += 1;
    }
    for (const { finding, range } of located) {
      if (isFormatCheckId(finding.ruleId)) {
        const latinFont = preferredLatinFont(opts.bodyFont) === "Arial" ? "Arial" : opts.bodyFont;
        // 「ギリシャ文字は Symbol フォント」 rewrites the text as well as the font
        // (π becomes a Symbol-font "p"), so the formatting goes on whatever
        // range the write leaves behind, not the one that is about to vanish.
        const target =
          finding.replacement === undefined
            ? range
            : range.insertText(finding.replacement, Word.InsertLocation.replace);
        if (applyFormatFix(finding.ruleId, target.font, latinFont)) applied += 1;
        continue;
      }
      if (finding.replacement === undefined) continue;
      range.insertText(finding.replacement, Word.InsertLocation.replace);
      applied += 1;
    }

    await context.sync();
    return { applied, skipped: requested.length + paragraphFixes.length - applied };
  });
}

/**
 * Orders findings so that a batch of edits inside one paragraph cannot corrupt
 * each other, and drops the ones that would.
 *
 * Two problems are handled here. Overlapping findings — 「更に」→「さらに」 and a
 * 表記ゆれ hit on the same 「更に」 — would each rewrite the other's text, so only
 * the first is kept. And a replacement of a different length shifts every offset
 * after it, so edits run right to left; by the time an earlier span is written,
 * nothing before it has moved.
 *
 * Exported for testing: this ordering is the only thing standing between a
 * multi-fix paragraph and silent corruption.
 */
export function orderForApply(findings: readonly Finding[]): Finding[] {
  // A finding with no replacement only changes formatting (bold, italic, font).
  // It shifts nothing, so it neither conflicts with its neighbours nor cares
  // about ordering — and it goes first, before any text length changes.
  const formatOnly = findings.filter((f) => f.replacement === undefined);
  const rewrites = findings.filter((f) => f.replacement !== undefined);

  const byParagraph = new Map<number, Finding[]>();
  for (const item of rewrites) {
    if (!byParagraph.has(item.paragraphIndex)) byParagraph.set(item.paragraphIndex, []);
    byParagraph.get(item.paragraphIndex)!.push(item);
  }

  const ordered: Finding[] = [];
  for (const paragraphIndex of [...byParagraph.keys()].sort((a, b) => a - b)) {
    const items = byParagraph.get(paragraphIndex)!.sort((a, b) => b.start - a.start || a.end - b.end);
    let boundary = Number.POSITIVE_INFINITY; // start of the last rewrite kept
    for (const item of items) {
      if (item.end > boundary) continue; // overlaps something already scheduled
      ordered.push(item);
      boundary = item.start;
    }
  }

  return [...formatOnly, ...ordered];
}

export type { Finding, Category, RuleSettings, FontInventory, FontUsage, InventoryItem, Occurrence };
