/**
 * The single list of everything the user can switch on or off.
 *
 * Two kinds of check exist for good reasons — text rules run on paragraph
 * strings, formatting checks need Word to answer "is this bold?" — but that
 * split is an implementation detail. 「ルール設定」 shows one list, so this module
 * joins the two sources with the descriptions from `src/core/catalog.ts`.
 */
import { ALL_RULES } from "../core/engine.ts";
import { RULE_DOCS, RULE_ENTRIES, RULE_GROUPS, enabledByDefault } from "../core/catalog.ts";
import type { Entry } from "../core/dict.ts";
import type { Category } from "../core/types.ts";
import { FORMAT_CHECK_INFO } from "./formatChecks.ts";

export interface CatalogItem {
  readonly id: string;
  readonly title: string;
  readonly category: Category;
  /** `format` checks read the document's formatting; `text` checks read the text. */
  readonly kind: "text" | "format";
  readonly summary: string;
  readonly example?: string;
  readonly defaultEnabled: boolean;
  /** Word list behind the rule, when it has one; each entry can be switched off. */
  readonly entries?: readonly Entry[];
  /** 表記ゆれの組。読むだけ（置換先は文書内の多数派で決まる）。 */
  readonly groups?: readonly (readonly string[])[];
}

function describe(id: string, title: string, category: Category, kind: "text" | "format"): CatalogItem {
  const doc = RULE_DOCS[id];
  return {
    id,
    title,
    category,
    kind,
    summary: doc?.summary ?? "",
    ...(doc?.example === undefined ? {} : { example: doc.example }),
    defaultEnabled: enabledByDefault(id),
    ...(RULE_ENTRIES[id] ? { entries: RULE_ENTRIES[id] } : {}),
    ...(RULE_GROUPS[id] ? { groups: RULE_GROUPS[id] } : {}),
  };
}

export const RULE_CATALOG: readonly CatalogItem[] = Object.freeze([
  ...ALL_RULES.map((rule) => describe(rule.id, rule.title, rule.category, "text")),
  ...FORMAT_CHECK_INFO.map((check) => describe(check.id, check.title, check.category, "format")),
]);

/** Rules that are off until the user asks for them. */
export const DEFAULT_DISABLED_RULES: readonly string[] = Object.freeze(
  RULE_CATALOG.filter((item) => !item.defaultEnabled).map((item) => item.id),
);

export function catalogItem(ruleId: string): CatalogItem | undefined {
  return RULE_CATALOG.find((item) => item.id === ruleId);
}

/** Display title for a finding's rule, whatever kind of check produced it. */
export function titleFor(ruleId: string): string {
  return catalogItem(ruleId)?.title ?? ruleId;
}
