/**
 * Builds a paragraph rule out of a word list.
 *
 * The one subtlety is compounds. 「更に」 is a real finding in 「更に検討した」 but a
 * false one in 「変更に伴い」, where it is just the tail of 変更 plus a particle.
 * Since every entry here is a whole word, a match that is glued to another kanji
 * on either side is almost always part of a longer compound, so it is skipped.
 * That trades a little recall for precision, which is the right way round for a
 * tool whose output a human reads line by line.
 */
import type { Entry } from "../dict.ts";
import { entryKey } from "../catalog.ts";
import type { Category, DocumentContext, Finding, ParagraphRule } from "../types.ts";
import { finding } from "../types.ts";
import { escapeRegExp, matchAll } from "../text.ts";

const KANJI = /[一-鿿㐀-䶿々]/u;
const LATIN = /[A-Za-z0-9]/u;

function isKanji(ch: string | undefined): boolean {
  return ch !== undefined && KANJI.test(ch);
}

function isLatin(ch: string | undefined): boolean {
  return ch !== undefined && LATIN.test(ch);
}

/**
 * True when `text[start..end)` is glued to a longer word on either side.
 *
 * Kanji: 「更に」 is real in 「更に検討した」 and false in 「変更に伴い」, where it is the
 * tail of 変更 plus a particle.
 *
 * Latin: the same trap in the journal list. 「J. Org. Chem」 is an entry because it
 * is missing its final period — but it also sits inside 「J. Org. Chemistry」, and
 * asking for a period there is nonsense.
 */
export function isPartOfCompound(text: string, start: number, end: number): boolean {
  const term = text.slice(start, end);
  if (isKanji(term[0]) && isKanji(text[start - 1])) return true;
  if (isKanji(term[term.length - 1]) && isKanji(text[end])) return true;
  if (isLatin(term[0]) && isLatin(text[start - 1])) return true;
  if (isLatin(term[term.length - 1]) && isLatin(text[end])) return true;
  return false;
}

/**
 * True when the preferred form is *already* written here.
 *
 * Entries that only add a character — 「J. Org. Chem」→「J. Org. Chem.」,
 * 「Chem. Commun」→「Chem. Commun.」 — match inside their own corrected form,
 * because the shorter string is a prefix of the longer one. Nothing is wrong
 * with text that already spells the target, so there is nothing to report.
 *
 * The length test is what keeps the opposite kind of entry working. 「Angew. Chem.
 * Int. Ed. Engl.」→「Angew. Chem. Int. Ed.」 *removes* a token, so the target is a
 * prefix of every match by construction; without the test, that entry could never
 * fire.
 */
export function alreadyCorrect(text: string, start: number, from: string, to: string): boolean {
  return to.length > from.length && text.startsWith(to, start);
}

export function dictionaryRule(spec: {
  id: string;
  category: Category;
  title: string;
  entries: readonly Entry[];
  /** Builds the finding message; receives the entry that matched. */
  message: (entry: Entry) => string;
}): ParagraphRule {
  // One alternation for the whole list, longest-first so 「することができる」 wins
  // over 「することが可能」-style prefixes of each other.
  const sorted = [...spec.entries].sort((a, b) => b.from.length - a.from.length);
  const pattern = new RegExp(sorted.map((e) => escapeRegExp(e.from)).join("|"), "gu");
  const byForm = new Map(sorted.map((e) => [e.from, e]));

  return {
    id: spec.id,
    category: spec.category,
    title: spec.title,
    kind: "paragraph",
    run(text: string, index: number, ctx: DocumentContext): Finding[] {
      const found: Finding[] = [];
      for (const m of matchAll(pattern, text)) {
        const entry = byForm.get(m[0]);
        if (!entry) continue;
        if (ctx.disabledEntries.has(entryKey(spec.id, entry.from))) continue;
        if (isPartOfCompound(text, m.index, m.index + m[0].length)) continue;
        if (alreadyCorrect(text, m.index, entry.from, entry.to)) continue;
        found.push(
          finding(spec, {
            severity: entry.severity,
            paragraphIndex: index,
            start: m.index,
            matched: m[0],
            replacement: entry.to,
            message: spec.message(entry),
          }),
        );
      }
      return found;
    },
  };
}

/** Standard message body: 「A」→「B」 plus the entry's note, when it has one. */
export function arrowMessage(prefix: string): (entry: Entry) => string {
  return (entry) =>
    `${prefix}：「${entry.from}」→「${entry.to}」${entry.note ? `（${entry.note}）` : ""}`;
}
